// Generated by build-assets.py from ani.wasm and anim_data.bin.
(function () {
  const encoded = { wasm: "", data: "" };
  window.AnimationAssets = {
    decode(name) {
      const binary = atob(encoded[name]);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      return bytes;
    }
  };
})();
